// The risk database (High-Value Protection spec §10, plan V3 §115–§118): one record per provider (its class and custody
// model, upgradeability, audits, bounty, TVL and volume when known, its security- and privacy-event histories), per
// asset (the issuer and its powers) and per route (generated by the campaign lab from measured quotes, dated — never
// edited by hand). Loaded from RISK_DB_DIR (default packages/swap-engine/risk/) and validated field by field: a
// malformed file adds nothing and is listed in `problems`. Nothing here is per user.
import { existsSync, readdirSync, readFileSync } from "fs";
import { dirname, join } from "path";
import { fileURLToPath } from "url";
import type { Gate, RiskClass } from "@privacy-wallet/protocol/wallet/campaign";
import type { Custody, RiskModelOverride } from "@privacy-wallet/protocol/wallet/riskClasses";

export interface Incident {
  provider: string;
  date: string; // ISO
  title: string;
  /** unknown when the record names none (the ninth review round, A9-2) */
  lossUsd?: number;
  /** a class the score has a penalty for; another costs the most (risk/security.ts) */
  class: "key-compromise" | "bridge" | "solver" | "api" | "liquidity" | "other" | (string & {});
  /** how long the incident keeps depressing the security score, in days (decays linearly) */
  halfLifeDays: number;
  source: string;
}
export interface PrivacyEvent { date: string; title: string; effect: "link-public" | "api-logs" | "kyc" | "metadata"; source?: string }
export type Upgradeability = "immutable" | "governance" | "timelock" | "multisig" | "admin";

export interface ProviderRiskRecord {
  provider: string;
  class?: RiskClass;
  custody?: Custody;
  bridgeModel?: string;
  validatorModel?: string;
  upgradeability?: Upgradeability;
  audits?: { firm: string; date: string; scope?: string; url?: string }[];
  lastCodeChange?: string;
  bugBounty?: { usdMax?: number; url?: string };
  tvlUsd?: number;
  volume30dUsd?: number;
  lastReviewed?: string;
  securityEvents?: Incident[];
  privacyEvents?: PrivacyEvent[];
  pFailPrior?: number;
  bandBps?: [number, number];
  gate?: Gate;
  notes?: string;
}
export interface AssetRiskRecord { symbol: string; issuer?: string | null; freezeRisk: boolean; pauseRisk?: boolean; blacklist?: boolean; decimals?: number; notes?: string }
export interface RoutePoint { usd: number; variant?: string; etaSeconds?: number | null; parts?: number | null; impactBps?: number | null; costVsOracleBps?: number | null; limits?: Record<string, string> | null }
export interface RouteRiskRecord { provider: string; pair: string; class?: RiskClass; measuredAt?: string; source?: string; servedUpToUsd?: number; impactBpsAtMax?: number; points?: RoutePoint[]; gate?: Gate; maxTrancheBps?: number; providerShareCapBps?: number; minTrancheUsd?: number; note?: string }

const CLASSES: RiskClass[] = ["R1", "R2", "R3", "R4", "R5", "R6", "R7"];
const CUSTODY: Custody[] = ["tss-vaults", "mpc-vault", "relayer-bridge", "cctp", "solver", "aggregator", "intent", "contract", "counterparty"];
const UPGRADE: Upgradeability[] = ["immutable", "governance", "timelock", "multisig", "admin"];
const GATES: Gate[] = ["source", "destination-submitted", "destination-final"];
/** The incident classes the security score has a penalty for (risk/security.ts INCIDENT_PENALTY); "other" is the V2 spec's own word. */
export const INCIDENT_CLASSES: readonly Incident["class"][] = ["key-compromise", "bridge", "solver", "api", "liquidity", "other"];
/** The half-life an incident record without a usable one is given: the risk database's own records use a year. */
export const DEFAULT_HALF_LIFE_DAYS = 365;
/**
 * An incident record as the score reads it (the ninth review round, 2026-11-04, A9-2): every record that names a provider and a date is
 * kept — a class without a penalty of its own costs the most (risk/security.ts), a half-life not above zero is the default one, a loss that
 * is no number is unknown. The eighth round's filter (D-L5, against a NaN score) had dropped the spec's own class "other", an "exploit", a
 * half-life of 0 and a null loss silently — no breaker, no R4, no narrowed band: the operator's emergency lever failing open.
 */
export function incidentOf(i: any): Incident | null {
  if (!i || typeof i.provider !== "string" || !i.provider || typeof i.date !== "string" || Number.isNaN(Date.parse(i.date))) return null;
  const halfLifeDays = typeof i.halfLifeDays === "number" && Number.isFinite(i.halfLifeDays) && i.halfLifeDays > 0 ? i.halfLifeDays : DEFAULT_HALF_LIFE_DAYS;
  const lossUsd = typeof i.lossUsd === "number" && Number.isFinite(i.lossUsd) && i.lossUsd >= 0 ? i.lossUsd : undefined;
  const cls = typeof i.class === "string" && i.class ? i.class : "unknown";
  const { lossUsd: _loss, ...rest } = i;
  return { ...rest, title: typeof i.title === "string" && i.title ? i.title : cls, class: cls, halfLifeDays, ...(lossUsd !== undefined ? { lossUsd } : {}) };
}
/** Whether a record is one the score can read (`incidentOf`). */
export const isIncident = (i: any): i is Incident => incidentOf(i) !== null;

/** Where an asset's symbol names its own chain (assets.ts HOME in @privacy-wallet/config): off it, a route record names the chain. */
const HOME_CHAIN: Record<string, string> = { BTC: "bitcoin", SOL: "solana", ETH: "ethereum", USDC: "ethereum", USDT: "ethereum" };
const labelOf = (a: { chain: string; symbol: string }) =>
  HOME_CHAIN[a.symbol.toUpperCase()] === a.chain ? a.symbol : `${a.symbol}(${a.chain.charAt(0).toUpperCase()}${a.chain.slice(1)})`;
/**
 * A route record's pair as the lab names it (the eighth review round, D-L1): "ETH>USDC(Base)", "ETH>ETH(Base)", "ETH>BTC". The lookups
 * had keyed by the symbols alone, so no Base route's record — its measured liquidity, its gate, its band — was ever found.
 */
export const routePairOf = (from: { chain: string; symbol: string }, to: { chain: string; symbol: string }): string => `${labelOf(from)}>${labelOf(to)}`;

function validProvider(x: any, file: string, problems: string[]): ProviderRiskRecord | null {
  if (!x || typeof x.provider !== "string") { problems.push(`${file}: no provider id`); return null; }
  if (x.class !== undefined && !CLASSES.includes(x.class)) { problems.push(`${file}: unknown class ${x.class}`); return null; }
  if (x.custody !== undefined && !CUSTODY.includes(x.custody)) { problems.push(`${file}: unknown custody ${x.custody}`); return null; }
  if (x.upgradeability !== undefined && !UPGRADE.includes(x.upgradeability)) { problems.push(`${file}: unknown upgradeability ${x.upgradeability}`); return null; }
  if (x.gate !== undefined && !GATES.includes(x.gate)) { problems.push(`${file}: unknown gate ${x.gate}`); return null; }
  if (x.pFailPrior !== undefined && !(typeof x.pFailPrior === "number" && x.pFailPrior >= 0 && x.pFailPrior <= 1)) { problems.push(`${file}: pFailPrior outside [0, 1]`); return null; }
  if (x.bandBps !== undefined && !(Array.isArray(x.bandBps) && x.bandBps.length === 2 && x.bandBps.every((b: unknown) => typeof b === "number") && x.bandBps[0] <= x.bandBps[1])) { problems.push(`${file}: bandBps must be [min, max]`); return null; }
  const securityEvents = Array.isArray(x.securityEvents)
    ? x.securityEvents.flatMap((i: unknown) => {
        const inc = incidentOf({ ...(i as object), provider: x.provider });
        return inc ? [inc] : [];
      })
    : undefined;
  if (Array.isArray(x.securityEvents) && securityEvents!.length !== x.securityEvents.length) problems.push(`${file}: ${x.securityEvents.length - securityEvents!.length} malformed security event(s) skipped`);
  return { ...x, ...(securityEvents ? { securityEvents } : {}) } as ProviderRiskRecord;
}
function validAsset(x: any, file: string, problems: string[]): AssetRiskRecord | null {
  if (!x || typeof x.symbol !== "string" || typeof x.freezeRisk !== "boolean") { problems.push(`${file}: an asset record needs symbol and freezeRisk`); return null; }
  return x as AssetRiskRecord;
}
function validRoute(x: any, file: string, problems: string[]): RouteRiskRecord | null {
  if (!x || typeof x.provider !== "string" || typeof x.pair !== "string") { problems.push(`${file}: a route record needs provider and pair`); return null; }
  if (x.gate !== undefined && !GATES.includes(x.gate)) { problems.push(`${file}: unknown gate ${x.gate}`); return null; }
  return x as RouteRiskRecord;
}

export class RiskDb {
  readonly providers = new Map<string, ProviderRiskRecord>();
  readonly assets = new Map<string, AssetRiskRecord>();
  readonly routes = new Map<string, RouteRiskRecord>();
  readonly problems: string[] = [];
  constructor(readonly dir: string) {}

  static load(dir: string): RiskDb {
    const db = new RiskDb(dir);
    const read = <T>(sub: string, validate: (x: any, file: string, problems: string[]) => T | null, put: (t: T) => void) => {
      const d = join(dir, sub);
      if (!existsSync(d)) return;
      for (const f of readdirSync(d).filter((n) => n.endsWith(".json")).sort()) {
        const file = `${sub}/${f}`;
        try { const t = validate(JSON.parse(readFileSync(join(d, f), "utf8")), file, db.problems); if (t) put(t); }
        catch (e) { db.problems.push(`${file}: ${(e as Error).message}`); }
      }
    };
    read<ProviderRiskRecord>("providers", validProvider, (p) => db.providers.set(p.provider, p));
    read<AssetRiskRecord>("assets", validAsset, (a) => db.assets.set(a.symbol.toUpperCase(), a));
    read<RouteRiskRecord>("routes", validRoute, (r) => db.routes.set(`${r.provider}|${r.pair}`, r));
    return db;
  }
  providerRisk(id: string): ProviderRiskRecord | null { return this.providers.get(id) ?? null; }
  assetRisk(symbol: string): AssetRiskRecord | null { return this.assets.get(symbol.toUpperCase()) ?? null; }
  routeRisk(pair: string, provider: string): RouteRiskRecord | null { return this.routes.get(`${provider}|${pair}`) ?? null; }
  /** The fields the shared risk model takes from the database for a provider (and a route, when one is recorded). */
  override(provider: string, pair?: string): RiskModelOverride | null {
    const p = this.providers.get(provider);
    const r = pair ? this.routes.get(`${provider}|${pair}`) : undefined;
    if (!p && !r) return null;
    const o: RiskModelOverride = {};
    if (p?.class) o.class = p.class;
    if (p?.custody) o.custody = p.custody;
    if (p?.pFailPrior !== undefined) o.pFailPrior = p.pFailPrior;
    if (p?.bandBps) o.bandBps = p.bandBps;
    if (r?.maxTrancheBps !== undefined) o.bandBps = [Math.min(o.bandBps?.[0] ?? 100, r.maxTrancheBps), r.maxTrancheBps];
    if (r?.gate ?? p?.gate) o.gate = (r?.gate ?? p?.gate) as Gate;
    return o;
  }
  /** Every security event on record, provider set. */
  incidents(): Incident[] {
    const out: Incident[] = [];
    for (const p of this.providers.values()) for (const i of p.securityEvents ?? []) out.push(i);
    return out;
  }
}

/** This module's directory, from its file URL (a string into fileURLToPath: the wallet's happy-dom tests replace the global URL class, whose relative resolution is not file-based). */
const HERE = import.meta.url.startsWith("file:") ? dirname(fileURLToPath(import.meta.url)) : process.cwd();
export const RISK_DB_DIR: string = process.env.RISK_DB_DIR ?? join(HERE, "..", "..", "risk");
let shared: RiskDb | null = null;
/** The service's database, loaded once. */
export function riskDb(): RiskDb { return (shared ??= RiskDb.load(RISK_DB_DIR)); }
/** Tests: replace the shared database. */
export function useRiskDb(db: RiskDb | null): void { shared = db; }
